package local.audit;
import java.util.*;import java.nio.file.*;import com.google.gson.*;import com.mojang.serialization.JsonOps;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.minecraft.core.registries.*;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.item.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.damagesource.*;
import net.spell_engine.internals.*;import net.spell_engine.internals.casting.*;import net.spell_engine.internals.container.*;
@Mod("phase_two_probe") public class WardRetirementProbe {
 int count;List<String> lines=new ArrayList<>();void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;lines.add(s);}
 public WardRetirementProbe(){NeoForge.EVENT_BUS.addListener(this::start);}
 void start(ServerStartedEvent event){var w=event.getServer().overworld();try{
  var reg=w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT);check(reg.get(Identifier.parse("fangs_enchantment:fangs")).isEmpty(),"Fangs registry removed");check(!net.neoforged.fml.ModList.get().isLoaded("scalarrpgutils"),"Scalar absent");check(net.neoforged.fml.ModList.get().isLoaded("paladins")&&net.neoforged.fml.ModList.get().isLoaded("wizards"),"RPG Series retained");
  var ops=w.registryAccess().createSerializationContext(JsonOps.INSTANCE);var legacy=JsonParser.parseString("{\"id\":\"minecraft:diamond_leggings\",\"count\":1,\"components\":{\"minecraft:enchantments\":{\"fangs_enchantment:fangs\":3,\"minecraft:unbreaking\":8}}}").getAsJsonObject();var gear=ItemStack.CODEC.parse(ops,legacy).getOrThrow();check(gear.is(Items.DIAMOND_LEGGINGS)&&gear.get(DataComponents.ENCHANTMENTS).size()==1,"Legacy leggings survive with valid enchantments");legacy.addProperty("id","minecraft:enchanted_book");var components=legacy.getAsJsonObject("components");components.add("minecraft:stored_enchantments",components.remove("minecraft:enchantments"));components.add("penchant:enchantment_progress",components.get("minecraft:stored_enchantments").deepCopy());var book=ItemStack.CODEC.parse(ops,legacy).getOrThrow();check(book.get(DataComponents.STORED_ENCHANTMENTS).size()==1,"Legacy stored enchantments and progress decode");var nbtOps=w.registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);check(ItemStack.CODEC.parse(nbtOps,JsonOps.INSTANCE.convertTo(net.minecraft.nbt.NbtOps.INSTANCE,legacy)).getOrThrow().is(Items.ENCHANTED_BOOK),"NBT migration preserves book");
  var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(w);p.setPos(0,80,0);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);var enemy=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);enemy.setPos(2,80,0);w.addFreshEntity(enemy);
  for(String school:List.of("arcane","fire","frost")){
   p.removeAllEffects();p.setAbsorptionAmount(0);p.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:"+school)).orElseThrow()).setBaseValue(12);var ward=PaladinRevamp.spell(p,"skill_tree_rpgs:"+school+"_tier_3_passive_2");var owner=(SpellContainerSource.Owner)p;var old=owner.getSpellContainers();owner.setSpellContainers(new SpellContainerSource.Result(old.activeContainer(),List.of(),List.of(ward),List.of(),List.of(new SpellContainerSource.SourcedContainer("probe",ItemStack.EMPTY,new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,"","",0,List.of(ward.unwrapKey().orElseThrow().identifier().toString()))))));owner.spellModifierCache().clear();((SpellCaster.Player)p).getCooldownManager().reset(null);
   SpellTriggers.onDamageTaken(p,p.damageSources().fall(),1);check(p.getAbsorptionAmount()==0,school+" excludes fall");SpellTriggers.onDamageTaken(p,p.damageSources().playerAttack(p),1);check(p.getAbsorptionAmount()==0,school+" excludes self");var hit=new SpellTriggers.Event(net.spell_engine.api.spell.Spell.Trigger.Type.DAMAGE_TAKEN,p,enemy,enemy);hit.damageSource=p.damageSources().mobAttack(enemy);hit.damageAmount=1;lines.add("DIAG "+school+" stage="+hit.stage+" guard="+WardHitRules.allowed(ward,hit)+" evaluate="+PaladinRevamp.evaluate(ward,ward.value().passive.triggers.getFirst(),hit));SpellTriggers.onDamageTaken(p,p.damageSources().mobAttack(enemy),1);lines.add("AFTER absorption="+p.getAbsorptionAmount()+" effects="+p.getActiveEffects()+" cd="+((SpellCaster.Player)p).getCooldownManager().isCoolingDown(ward));check(p.getAbsorptionAmount()==4,school+" native enemy hit grants four HP at12 power");var effect=p.getEffect(PaladinRevamp.effect("skill_tree_rpgs:"+school+"_ward"));check(effect!=null&&effect.getDuration()==120,school+" six-second shield");check(((SpellCaster.Player)p).getCooldownManager().isCoolingDown(ward),school+" cooldown spent");check(ward.value().cost.cooldown.duration==12,school+" twelve-second cooldown");
  }
  Files.writeString(Path.of("phase-two-result.txt"),"PASS "+count+" checks\n");
 }catch(Throwable e){e.printStackTrace();try{Files.writeString(Path.of("phase-two-result.txt"),"FAIL "+e);}catch(Exception ignored){}}finally{try{Files.write(Path.of("phase-two-checks.txt"),lines);}catch(Exception ignored){}event.getServer().halt(false);}}
}
